-- 065_discount_delivery_voyage_management.sql
-- 할인/시내·지방배송/항차별 총액 관리 기반.
-- Existing freight logic remains central; this migration only adds metadata/matching.

alter table public.customer_rate_overrides
  add column if not exists company_name text not null default '',
  add column if not exists group_name text not null default '',
  add column if not exists source_detail text not null default '';

alter table public.shipments
  add column if not exists special_note_auto text not null default '';

create table if not exists public.local_delivery_profiles (
  id bigint generated always as identity primary key,
  route_key text not null,
  source_no integer,
  customer_name text not null default '',
  alternate_name text not null default '',
  company_name text not null default '',
  phone text not null default '',
  phone_display text not null default '',
  delivery_type text not null default 'province'
    check (delivery_type in ('province','city')),
  local_company text not null default '',
  destination_address text not null default '',
  paid_by text not null default '',
  notes text not null default '',
  active boolean not null default true,
  updated_at timestamptz not null default now(),
  unique(route_key, source_no)
);

create index if not exists local_delivery_profiles_route_idx
  on public.local_delivery_profiles(route_key);
create index if not exists local_delivery_profiles_phone_idx
  on public.local_delivery_profiles(phone);

alter table public.local_delivery_profiles enable row level security;

drop policy if exists local_delivery_read_authenticated on public.local_delivery_profiles;
drop policy if exists local_delivery_admin_write on public.local_delivery_profiles;
create policy local_delivery_read_authenticated on public.local_delivery_profiles
  for select using (auth.uid() is not null and public.is_approved_user());
create policy local_delivery_admin_write on public.local_delivery_profiles
  for all using (public.current_role()='admin')
  with check (public.current_role()='admin');

grant select on public.local_delivery_profiles to authenticated;
grant insert, update, delete on public.local_delivery_profiles to authenticated;
grant usage, select on sequence public.local_delivery_profiles_id_seq to authenticated;

create or replace function public.phone_matches(a text, b text)
returns boolean
language sql
immutable
as $$
  with p as (
    select public.normalize_phone(a) aa, public.normalize_phone(b) bb
  )
  select case
    when aa='' or bb='' then false
    when aa=bb then true
    when length(aa)>=8 and length(bb)>=8 then right(aa,8)=right(bb,8)
    else false
  end
  from p
$$;

create or replace function public.route_base_key_for_label(p_route text)
returns text
language plpgsql
stable
security definer
set search_path=public
as $$
declare
  v_key text;
begin
  begin
    select coalesce(nullif(base_route_key,''), route_key)
      into v_key
    from public.route_definitions
    where display_name=p_route or route_key=p_route
    order by case when display_name=p_route then 0 else 1 end
    limit 1;
  exception when undefined_table then
    v_key := null;
  end;

  if coalesce(v_key,'') <> '' then return v_key; end if;
  return case p_route
    when '한국->라오스 해상' then 'kr_la_sea'
    when '한국->라오스 항공' then 'kr_la_air'
    when '라오스->한국 항공 특송' then 'la_kr_air_exp'
    when '라오스->태국 내륙' then 'la_th_land'
    when '태국->라오스 내륙' then 'th_la_land'
    when '라오스->베트남 내륙' then 'la_vn_land'
    when '베트남->라오스 내륙' then 'vn_la_land'
    when '라오스->중국 내륙' then 'la_ch_land'
    when '중국->라오스 내륙' then 'ch_la_land'
    when '라오스->캄보디아 내륙' then 'la_kh_land'
    when '캄보디아->라오스 내륙' then 'kh_la_land'
    else p_route
  end;
end
$$;

create or replace function public.compute_shipment_special_note(
  p_route text,
  p_name text,
  p_phone text
)
returns text
language plpgsql
stable
security definer
set search_path=public
as $$
declare
  v_route_key text := public.route_base_key_for_label(p_route);
  v_group text := '';
  v_discount numeric := 0;
  v_delivery text := '';
  v_discount_text text := '';
begin
  if public.normalize_phone(p_phone) <> '' and public.normalize_person_name(p_name) <> '' then
    select coalesce(group_name,''), coalesce(discount_percent,0)
      into v_group, v_discount
    from public.customer_rate_overrides r
    where r.active=true
      and (r.route_key=v_route_key or r.route_key='all')
      and public.phone_matches(r.phone,p_phone)
      and (
        public.normalize_person_name(r.customer_name)=public.normalize_person_name(p_name)
        or (coalesce(r.company_name,'')<>'' and public.normalize_person_name(r.company_name)=public.normalize_person_name(p_name))
      )
    order by case when r.route_key=v_route_key then 0 else 1 end, r.id
    limit 1;

    select case when d.delivery_type='city' then '시내 배송' else '지방배송' end
      into v_delivery
    from public.local_delivery_profiles d
    where d.active=true
      and d.route_key=v_route_key
      and public.phone_matches(d.phone,p_phone)
      and (
        public.normalize_person_name(d.customer_name)=public.normalize_person_name(p_name)
        or (coalesce(d.alternate_name,'')<>'' and public.normalize_person_name(d.alternate_name)=public.normalize_person_name(p_name))
        or (coalesce(d.company_name,'')<>'' and public.normalize_person_name(d.company_name)=public.normalize_person_name(p_name))
      )
    order by d.source_no nulls last, d.id
    limit 1;
  end if;

  if coalesce(v_discount,0)>0 then
    v_discount_text := concat(
      case when btrim(v_group)='' then '' else btrim(v_group)||' 회원 ' end,
      trim(to_char(v_discount*100,'FM999990.##')),
      '% 할인'
    );
  end if;

  return concat_ws(' / ', nullif(v_discount_text,''), nullif(v_delivery,''));
end
$$;

create or replace function public.shipments_special_note_auto_trigger()
returns trigger
language plpgsql
security definer
set search_path=public
as $$
begin
  new.special_note_auto := public.compute_shipment_special_note(
    new.route,
    new.consignee_name,
    new.consignee_phone
  );
  return new;
end
$$;

drop trigger if exists shipments_special_note_auto_trg on public.shipments;
create trigger shipments_special_note_auto_trg
before insert or update of route, consignee_name, consignee_phone
on public.shipments
for each row execute function public.shipments_special_note_auto_trigger();

create or replace function public.admin_refresh_shipment_special_notes()
returns integer
language plpgsql
security definer
set search_path=public
as $$
declare
  v_count integer;
begin
  if public.current_role() <> 'admin' then
    raise exception 'admin only';
  end if;
  update public.shipments s
  set special_note_auto=public.compute_shipment_special_note(
    s.route,s.consignee_name,s.consignee_phone
  );
  get diagnostics v_count = row_count;
  return v_count;
end
$$;
grant execute on function public.admin_refresh_shipment_special_notes() to authenticated;

comment on column public.shipments.special_note_auto is
'자동 매칭 특이사항. 기존 Excel 발신인(sender_name) 수기 내용은 보존하고, 할인/시내·지방배송 자동 표시는 이 컬럼에 별도 저장.';
comment on table public.local_delivery_profiles is
'BASE Excel 시내, 지방배송 sheet 기반 고객별 배송 정보. white=province, green=city, yellow-highlighted E/F preferred.';

