-- Existing shipment rows are refreshed immediately after the Excel seed is loaded.
update public.shipments s
set special_note_auto = public.compute_shipment_special_note(
  s.route, s.consignee_name, s.consignee_phone
);

-- Excel bulk rows now expose the full calculation/mapping fields needed by
-- 특이사항 editing and voyage-total calculation. Existing callers may ignore extras.
drop function if exists public.admin_excel_bulk_rows(text, integer, text);
create function public.admin_excel_bulk_rows(
  p_route text,
  p_year integer,
  p_voyage text
)
returns table(
  id bigint,
  box_number text,
  invoice_number text,
  route text,
  shipment_year integer,
  voyage text,
  sender_name text,
  special_note_auto text,
  consignee_name text,
  consignee_phone text,
  contents text,
  quantity integer,
  weight_kg numeric,
  length_cm numeric,
  width_cm numeric,
  height_cm numeric,
  receipt_number text,
  unloading_zone text,
  notes text,
  received_at timestamptz,
  data_locked boolean
)
language plpgsql
security definer
set search_path=public
as $$
begin
  if public.current_role() <> 'admin' then
    raise exception '관리자(총괄) 권한이 필요합니다.';
  end if;
  return query
  select s.id, s.box_number, s.invoice_number, s.route, s.shipment_year,
         s.voyage, s.sender_name, s.special_note_auto,
         s.consignee_name, s.consignee_phone, s.contents, s.quantity,
         s.weight_kg, s.length_cm, s.width_cm, s.height_cm,
         s.receipt_number, s.unloading_zone, s.notes, s.received_at,
         s.data_locked
  from public.shipments s
  where s.route=p_route and s.shipment_year=p_year and s.voyage=p_voyage
    and s.deletion_requested_at is null
  order by nullif(btrim(s.receipt_number),'') nulls last,
           btrim(s.receipt_number), s.box_number, s.id;
end
$$;
grant execute on function public.admin_excel_bulk_rows(text, integer, text) to authenticated;

-- Add 특이사항(sender_name) to Excel bulk editor RPC.
drop function if exists public.admin_excel_bulk_update(bigint,text,text,text,text,text,text);
create function public.admin_excel_bulk_update(
  p_shipment_id bigint,
  p_box_number text,
  p_sender_name text,
  p_consignee_name text,
  p_consignee_phone text,
  p_receipt_number text,
  p_unloading_zone text,
  p_notes text
)
returns void
language plpgsql
security definer
set search_path=public
as $$
declare
  current_row public.shipments%rowtype;
  next_key text;
begin
  if public.current_role() <> 'admin' then
    raise exception '관리자(총괄) 권한이 필요합니다.';
  end if;
  select * into current_row from public.shipments where id=p_shipment_id;
  if not found then raise exception '화물을 찾을 수 없습니다.'; end if;
  if nullif(btrim(p_box_number),'') is null then
    raise exception '박스번호는 비워둘 수 없습니다.';
  end if;
  if exists (
    select 1 from public.shipments s
    where s.id<>p_shipment_id and s.route=current_row.route
      and s.shipment_year=current_row.shipment_year
      and s.voyage=current_row.voyage
      and s.box_number=btrim(p_box_number)
      and s.deletion_requested_at is null
  ) then raise exception '같은 항차에 이미 존재하는 박스번호입니다.'; end if;
  next_key := current_row.route||'|'||coalesce(current_row.shipment_year::text,'')||'|'||current_row.voyage||'|'||btrim(p_box_number);
  update public.shipments
  set box_number=btrim(p_box_number), import_key=next_key,
      sender_name=coalesce(p_sender_name,''),
      consignee_name=coalesce(p_consignee_name,''),
      consignee_phone=coalesce(p_consignee_phone,''),
      receipt_number=coalesce(p_receipt_number,''),
      unloading_zone=coalesce(p_unloading_zone,''),
      notes=coalesce(p_notes,'')
  where id=p_shipment_id;
end
$$;
grant execute on function public.admin_excel_bulk_update(bigint,text,text,text,text,text,text,text) to authenticated;
